@import "@fontsource-variable/figtree";
@import "@fontsource-variable/figtree/wght-italic.css";
@import "@fontsource-variable/newsreader/opsz.css";
@import "@fontsource-variable/antonio";

/* Light (faithful): a white page and deep navy (#2e3348) ink. Sunflower yellow (#ffd000) is
   the one brand colour, with navy text on it. Cards are a warm cream (#f8f8f1), the snack panel
   a warmer cream (accent), quote cards a pale mint (muted). Two full-bleed bands: plum
   (secondary, the footer) and deep teal (highlight, the member stories), both with white text.
   The ring is the violet link colour. The glow is a paler yellow for the podcast band's blobs;
   chart-1 is the sage figure tile. */
:root {
  --background: #ffffff;
  --foreground: #2e3348;
  --card: #f8f8f1;
  --card-foreground: #2e3348;
  --popover: #ffffff;
  --popover-foreground: #2e3348;
  --primary: #ffd000;
  --primary-foreground: #2e3348;
  --secondary: #532d3c;
  --secondary-foreground: #ffffff;
  --muted: #eef6f4;
  --muted-foreground: #4b4f60;
  --accent: #efecd7;
  --accent-foreground: #2e3348;
  --destructive: #c8323c;
  --destructive-foreground: #ffffff;
  --border: #e3e3e3;
  --input: #767676;
  --ring: #5755ce;
  --highlight: #2d4343;
  --highlight-foreground: #ffffff;
  --glow: #ffe45c;
  --chart-1: #c9e1da;
  --chart-2: #2e3348;
  --chart-3: #ffd000;
  --chart-4: #532d3c;
  --chart-5: #2d4343;
  --sidebar: #f8f8f1;
  --sidebar-foreground: #2e3348;
  --sidebar-primary: #ffd000;
  --sidebar-primary-foreground: #2e3348;
  --sidebar-accent: #efecd7;
  --sidebar-accent-foreground: #2e3348;
  --sidebar-border: #e3e3e3;
  --sidebar-ring: #5755ce;

  --typeface-body: "Figtree Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Figtree Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 1rem; /* 16px tiles and quote cards; 2xl = the 24px panels */
  --page-width: 83rem; /* a 1296px column + two 16px gutters: 72px margins at 1440 */
  --page-gutter: 1rem;
  --section-y: 4.5rem;

  /* theme-only faces used by the zoe blocks (they fall back to the display face elsewhere) */
  --zoe-serif: "Newsreader Variable", Georgia, serif;
  --zoe-condensed: "Antonio Variable", "Arial Narrow", sans-serif-condensed, sans-serif;
}

/* Dark sibling: a deep navy page (#1b1e2c) with cream ink, raised navy cards, the same
   sunflower yellow, a darker plum and teal for the bands, and a deep mint-grey for quotes. */
.dark {
  --background: #1b1e2c;
  --foreground: #f8f8f1;
  --card: #262a3c;
  --card-foreground: #f8f8f1;
  --popover: #262a3c;
  --popover-foreground: #f8f8f1;
  --primary: #ffd000;
  --primary-foreground: #2e3348;
  --secondary: #44222f;
  --secondary-foreground: #ffffff;
  --muted: #263433;
  --muted-foreground: #b4b8c6;
  --accent: #34322a;
  --accent-foreground: #f8f8f1;
  --destructive: #ff6b73;
  --destructive-foreground: #ffffff;
  --border: #3a3f55;
  --input: #6b7088;
  --ring: #9a98ff;
  --highlight: #22393a;
  --highlight-foreground: #ffffff;
  --glow: #ffe45c;
  --chart-1: #3b5550;
  --chart-2: #2e3348;
  --chart-3: #ffd000;
  --chart-4: #6a3a4d;
  --chart-5: #2d4343;
  --sidebar: #262a3c;
  --sidebar-foreground: #f8f8f1;
  --sidebar-primary: #ffd000;
  --sidebar-primary-foreground: #2e3348;
  --sidebar-accent: #34322a;
  --sidebar-accent-foreground: #f8f8f1;
  --sidebar-border: #3a3f55;
  --sidebar-ring: #9a98ff;
}
